from pathlib import Path
import hashlib,json,shutil,pandas as pd,zipfile
R=Path.cwd();E=R/'experiments/standardization';P=E/'prepared';P.mkdir(exist_ok=True);old=R/'experiments/priority_controls';oldplan=old/'prepared/plan.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,a):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(a,indent=2,sort_keys=True)+'\n',encoding='utf-8')
assert sha(oldplan)==json.loads((old/'plan_summary.json').read_text())['plan_sha256'];a=json.loads(oldplan.read_text(encoding='utf-8'))
for n in ['controls.py','study_common.py']:shutil.copy2(old/'code'/n,E/'code'/n)
