jobs=[];baseline={}
for j in a['existing_heads']:
 assert j['ratio'] in [.5,.8]
 for kind in ['split','cohort']:
  src=old/'prepared'/j[kind];assert sha(src)==j[kind+'_sha256'];dst=P/j[kind];dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dst)
 folder=R/('experiments/score_audit_private/roberta_heads' if j['encoder']=='RoBERTa' else 'experiments/second_encoder/completed_audit/downloaded/results')/j['job_id'];rp=folder/'result.json';assert sha(rp)==j['result_sha256'];result=json.loads(rp.read_text(encoding='utf-8'))
 baseline[j['job_id']]={'initial_parameter_sha256':result['initial_parameter_sha256'],'selected_optimizer_update':result['selected_optimizer_update'],'result_sha256':j['result_sha256'],'original_job':result['job'],'initialization_validation':result['initialization_validation'],'selected_validation':result['selected_validation'],'final_validation':result['final_validation'],'test_targets':result['test_targets']}
 job={k:j[k] for k in ['encoder','source','ratio','loss','seed','fixed_n','split','cohort','split_sha256','cohort_sha256']};job.update(family='standardized_mlp',split_seed=42,baseline_job_id=j['job_id'],job_id=f"standard_{j['encoder']}_{j['source']}_p{j['ratio']:.2f}_{j['loss']}_r{j['seed']}");job['job_sha256']=hashlib.sha256(json.dumps(job,sort_keys=True).encode()).hexdigest();jobs.append(job)
assert len(jobs)==len(baseline)==72
# Reuse exact archived random initial heads across Torch versions; no new training.
for seed in range(3):
 oldid=f'bert_arch_coaid_s42_p0.50_tbase_unweighted_ce_r{seed}'
 folder=R/'experiments/second_encoder/completed_audit/downloaded/results'/oldid
 result=json.loads((folder/'result.json').read_text(encoding='utf-8'))
 src=folder/'initial_model.pt';assert sha(src)==result['files_sha256']['initial_model.pt']
 dst=P/f'initial_states/seed{seed}.pt';dst.parent.mkdir(exist_ok=True);shutil.copy2(src,dst)
write(P/'baseline_metadata.json',baseline)
frames=[]
for n in ['linear_decision_evaluations.csv','mirror_decision_evaluations.csv']:
 p=R/'deliverables/paper_v1_8'/n;mh=json.loads((p.parent/'deliverable_hashes.json').read_text(encoding='utf-8'));assert sha(p)==mh[n];frames.append(pd.read_csv(p))
f=pd.concat(frames,ignore_index=True).query("family == 'existing_mlp'").copy();assert len(f)==648 and f.job_id.nunique()==72 and set(f.job_id)==set(baseline);assert not f.duplicated(['job_id','target','rule']).any();f.to_csv(P/'baseline_decisions.csv',index=False,lineterminator='\n')
frozen={str(p.relative_to(E)).replace('\\','/'):sha(p) for p in sorted(P.rglob('*')) if p.is_file() and p.name!='plan.json'}
for p in sorted((E/'code').glob('*')):
 if p.is_file():frozen[str(p.relative_to(E)).replace('\\','/')]=sha(p)
plan={'version':1,'source_plan_sha256':sha(oldplan),'spec':{'sources':['coaid','fakenewsnet','liar'],'encoders':['RoBERTa','BERT'],'split_seed':42,'shares':[.5,.8],'losses':['unweighted_ce','weighted_ce'],'seeds':[0,1,2],'features':'Original frozen first-token caches; no encoder inference','scaler':'Sampled source training cohort only: float64 mean/population SD, zero SD becomes1, transform to float32 unchanged across source validation/all target tests','head':'Original 768->256 ReLU/dropout0.3->2 with matched initialization fingerprint','optimizer':'AdamW lr0.001 weight_decay0.0001 clip_norm1, 30 full-batch updates, original3-warmup/cosine schedule','selection':'earliest best post-update source-validation macro-F1; initialization excluded','endpoints':['initial','training-ever source-validation','selected','final'],'decision_rules':['raw','source_prior','source_val_threshold'],'excluded':['center-only arm','share0.20','graphs','Monant','fine-tuning','pooling changes','hyperparameter search','target-based calibration'],'statistics':'Three paired seeds on one split; descriptive, no independent target/rule replication claims'},'caches':a['caches'],'jobs':jobs,'frozen_files':frozen,'counts':{'new_fits':72,'optimizer_updates_per_fit':30,'planned_optimizer_updates':2160,'reused_raw_reference_heads':72,'selected_decision_rule_target_records':648}}
write(P/'plan.json',plan);ph=sha(P/'plan.json');write(E/'plan_summary.json',{'plan_sha256':ph,'counts':plan['counts'],'training_executed_locally':False})
write(E/'approval_record.json',{'status':'approved','approved_plan_sha256':ph,'approved_by':'Human user in this research chat','approval_date_local':'2026-10-17','approval_text':'lets proceed. Create a file that I can run in Colab','context':'Response to the concrete 72-fit standardization plan; Colab execution by the author. Preparation only locally. No centering-only or additional fits authorized.'})
protocol='''# Approved standardized-feature control\n\n72 new text-only fits: two encoders, three sources, shares .50/.80, two losses and seeds0–2 on the exact existing split42/cohorts. Each is30 full-batch updates with the original head/AdamW/warmup/cosine setup and paired initial weights. No new encoding, raw-text loading, graph/Monant training, pooling, tuning, centering-only arm or .20 grid.\n\nCompute each coordinate mean/population SD from that job's sampled source training cohort only, without CE weights. Zero SD becomes1. Statistics are float64; transformed features float32. Freeze the source-cohort transform for all validation/test populations. This differs from the earlier descriptive geometry diagnostic on the full training reference pool. The intervention combines centering and scaling; it does not isolate them.\n\nSelection is earliest best post-update source-validation macro-F1, excluding initialization. Save initial, selected and final weights/margins; log all30 post-update source-validation outcomes and keep training-ever collapse separate. Selected-only raw/prior/source-validation-threshold decisions follow the completed control definitions. No target labels/prevalence select checkpoints, transforms or decision rules. Original full source training groups define target duplicate exclusions.\n\nRaw baselines already exist; no raw refits are added. The verifier checks72 result records, scaler provenance,30-update trajectories, earliest selection, saved prediction metrics and initial/selected/final weight replays, then writes paired aggregate comparisons. These records do not establish independent replication counts.\n\nOpen Discover_Standardization_72_Fits.ipynb in Colab and Run all. CPU works; selecting a GPU before starting is optional and auto-detected. Keep the same runtime/software/device while resuming. Finished job directories are hash-checked and skipped; interrupted attempts are preserved separately and restart from their seed. Changed runtime/code or damaged results stop rather than mix outputs.\n\nPackage inputs: frozen split/cohort manifests and baseline aggregates. Six original embedding caches are copied read-only from their recorded Discover paths into ephemeral Colab storage, with SHA-256 verification. No original Drive source data/results are edited. New private outputs: New_Experiments/standardization_results/v1. Row-level margins/labels and weights stay private. Share only analysis aggregates after review.\n\nAuthor authorization is bound to prepared/plan.json in approval_record.json. New training has not occurred during preparation. No fixed wall-clock estimate has been validated.\n'''
(E/'PROTOCOL.md').write_text(protocol,encoding='utf-8')
print('Frozen72-job plan built:',ph);print('Baseline rows',len(f),'caches',len(a['caches']))
